    o.yAxis={type:'category',data:shown.map(p=>p.name),axisLine:{show:false},axisTick:{show:false},axisLabel:{fontSize:9,color:'#8c9c7b',width:105,overflow:'truncate'}};
    o.tooltip={...o.tooltip,trigger:'item',formatter:p=>{const r=shown[p.dataIndex];return `<b>${e(r.name)}</b><br>Турниров: ${r.games}<br>Средний перфоманс B: <b>${num(r.avgPerformance)}</b><br>Игр с оценкой: ${num(r.performanceGames)}<br><small>Нажмите, чтобы выбрать игрока</small>`;}};
    o.series=[{type:'bar',data:shown.map(p=>p.games),barMaxWidth:13,itemStyle:{color:colors.green,borderRadius:[0,4,4,0]},label:{show:true,position:'right',fontSize:9,color:'#8da077'}}];
